def render(messages):
    items = "".join(
        f'<li data-seq="{m["seq"]}"><b>{m["author"]}</b> {m["text"]}</li>' for m in messages)
    return f'<ol class="transcript">{items}</ol>'


def preview():
    return render([{"seq": 1, "author": "Builder", "text": "patch ready"},
                   {"seq": 2, "author": "Critic", "text": "one test fails"},
                   {"seq": 5, "author": "Builder", "text": "fixed"}])

